{
  "name": "JULABO F32-HD循环冷却器",
  "name_en": "JULABO F32-HD recirculating chiller",
  "manufacturer": "JULABO",
  "description": "JULABO F32-HD 是一款实验室循环冷却器/恒温设备，通过循环冷却液为外部仪器或实验装置提供稳定的温度控制，适用于需要持续散热和恒温运行的实验系统。",
  "description_en": "The JULABO F32-HD is a laboratory recirculating chiller/thermostatic unit that provides stable temperature control to external instruments or experimental setups by circulating coolant. It is used in lab systems that require continuous heat removal and controlled operating temperature.",
  "tag_hints": [
    "recirculating chiller",
    "laboratory temperature control",
    "coolant circulation",
    "thermostatic bath",
    "external equipment cooling",
    "RS-232 instrument control"
  ],
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化循环冷却器通信连接。",
      "description_en": "Initialize communication with the recirculating chiller."
    },
    {
      "action_name": "auto-read",
      "description": "从循环冷却器读取返回数据。",
      "description_en": "Read returned data from the recirculating chiller."
    },
    {
      "action_name": "auto-write",
      "description": "向循环冷却器发送命令。",
      "description_en": "Send a command to the recirculating chiller."
    },
    {
      "action_name": "auto-get_identifier",
      "description": "获取设备标识信息。",
      "description_en": "Get the device identification information."
    },
    {
      "action_name": "auto-start_thermostat",
      "description": "启动循环冷却器的恒温/制冷运行。",
      "description_en": "Start the chiller's thermostatic/cooling operation."
    },
    {
      "action_name": "auto-stop_thermostat",
      "description": "停止循环冷却器的恒温/制冷运行。",
      "description_en": "Stop the chiller's thermostatic/cooling operation."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取设备状态。",
      "description_en": "Get the device status."
    }
  ]
}

